var MSSCustodyBulkFileUpload = Class.create();
MSSCustodyBulkFileUpload.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {




    /*
Schema for Bulk Level and Trade Level File upload functions

bulkLevelParse   ------>   bulkErrorValidation ------>  createBulkCaseTask  ------> Creates case and flow starts triggering due to case creation
(Reads the Excel)			(Segregation of Valid/		(Case Creation for			
                                invalid Trades)			valid trades)
                                   |
                                   |
                                   |--------------------> populateErrorRecord ------> Populates the new field (TBD) in bulk for audit


tradeLevelParse   ------>   bulkErrorValidation ------>  createBulkCaseTask  ------> Creates case and flow starts triggering due to case creation
(Reads the Excel)			(Segregation of Valid/		(Case Creation for			
                                invalid Trades)			valid trades)
                                   |
                                   |
                                   |--------------------> populateErrorRecord ------> Populates the new field (TBD) in bulk for audit
*/



    //clinet side testing

    bulkLevelParseClient: function() {
        /*

        This function will be called from the bulk File Uplaod record producer which will parse all the contents of the excel and return
        an array of elements. This will be used for the upload type of BUlk Upload


        Sample output Format
        {
        "TradeReference": "R-42342-00-00",
        "OwningBusiness": "DCC HK"
        }, {
        "tradeReference": "R-42223-00-01",
            "OwningBusiness": "DCC HK"
        }, {
            "tradeReference": "R-23242-00-02",
        "OwningBusiness": "DCC HK"
        }

        */

        var bulkRecID = this.getParameter('sysparm_bulkID');
        gs.addInfoMessage('bulkRec ' + bulkRecID);
        var owningBusiness = this.getParameter('sysparm_market');

        try {

            var bulkexcelRowArray = [];
            //getting the attachment
            var bulkgetAttachment = new GlideRecord('sys_attachment');
            bulkgetAttachment.addEncodedQuery('table_sys_id=' + bulkRecID);
            bulkgetAttachment.query();
            if (bulkgetAttachment.next()) {
                var bulkattachmentRec = bulkgetAttachment.getValue('sys_id');
            }
            //getting attachment

            var bulkattachment = new GlideSysAttachment(); //method to get the contents of the attachment
            var bulkattachmentDetails = bulkattachment.getContentStream(bulkattachmentRec); //getting content of the EXcel

            var bulkparser = new sn_impex.GlideExcelParser(); //method to parse the content of the Excel
            bulkparser.setSource(bulkattachmentDetails); //setting the source to parse the content from the stream

            var bulkgetSheet = bulkparser.getSheetNames(); //getting the sheet name to fetch details
            bulkparser.setSheetName(bulkgetSheet); //setting the sheet to parse

            if (bulkparser.parse()) { //converting into readable format using parse

                while (bulkparser.next()) { //iterating over each row
                    var bulkgetRows = bulkparser.getRow(); //reading row by row
                    bulkgetRows.business = owningBusiness.toString(); //add the owning business for each array item which will be used for error validation which will be from record producer
                    var bulkrowObj = JSON.stringify(bulkgetRows); //holds the rows of Excel as comma sepearated
                    bulkexcelRowArray.push(bulkrowObj + '');

                }
            }

            gs.addInfoMessage("Total Records " + bulkexcelRowArray.toString());


            this.bulkErrorValidation(bulkexcelRowArray, bulkRecID, owningBusiness);

        } catch (ex) {
            gs.info('Error Received from bulkLevelParse ' + ex);
        }


    },


    //client side testing




















    bulkLevelParse: function(bulkRecID, owningBusiness) {
        /*

        This function will be called from the bulk File Uplaod record producer which will parse all the contents of the excel and return
        an array of elements. This will be used for the upload type of BUlk Upload


        Sample output Format
        {
        "TradeReference": "R-42342-00-00",
        "OwningBusiness": "DCC HK"
        }, {
        "tradeReference": "R-42223-00-01",
            "OwningBusiness": "DCC HK"
        }, {
            "tradeReference": "R-23242-00-02",
        "OwningBusiness": "DCC HK"
        }

        */

        try {

            var bulkexcelRowArray = [];
            //getting the attachment
            var bulkgetAttachment = new GlideRecord('sys_attachment');
            bulkgetAttachment.addEncodedQuery('table_sys_id=' + bulkRecID);
            bulkgetAttachment.query();
            if (bulkgetAttachment.next()) {
                var bulkattachmentRec = bulkgetAttachment.getValue('sys_id');
            }
            //getting attachment

            var bulkattachment = new GlideSysAttachment(); //method to get the contents of the attachment
            var bulkattachmentDetails = bulkattachment.getContentStream(bulkattachmentRec); //getting content of the EXcel

            var bulkparser = new sn_impex.GlideExcelParser(); //method to parse the content of the Excel
            bulkparser.setSource(bulkattachmentDetails); //setting the source to parse the content from the stream

            var bulkgetSheet = bulkparser.getSheetNames(); //getting the sheet name to fetch details
            bulkparser.setSheetName(bulkgetSheet); //setting the sheet to parse

            if (bulkparser.parse()) { //converting into readable format using parse

                while (bulkparser.next()) { //iterating over each row
                    var bulkgetRows = bulkparser.getRow(); //reading row by row
                    bulkgetRows.business = owningBusiness.toString(); //add the owning business for each array item which will be used for error validation which will be from record producer
                    var bulkrowObj = JSON.stringify(bulkgetRows); //holds the rows of Excel as comma sepearated
                    bulkexcelRowArray.push(bulkrowObj + '');

                }
            }

            var recordsinExcel = parseInt(bulkexcelRowArray.length);

            //return bulkexcelRowArray;

            if (recordsinExcel != 0) {

                var errorRecords = this.bulkErrorValidation(bulkexcelRowArray, bulkRecID, owningBusiness);
                return errorRecords;
            } else {
                return 'No records Found';
            }

        } catch (ex) {
            gs.info('Error Received from bulkLevelParse ' + ex);
        }


    },



    tradeLevelParse: function(bulkRecID) {

        /*
        This function will be called from the bulk File Uplaod record producer which will parse all the contents of the excel and return
        an array of elements. This will be used for the upload type of Trade Upload

        Output Sample Format

        [{
        "TradeRef": "R-205-3345",
            "TradeID": "HK-HSBC-212121212-2323",
        "LegacyStatus": "CONF",
        "OwningBusiness": "DCC HK"
        }, {
        "TradeRef": "D-238-2233",
        "TradeID": "AU-HSBC-212121212-2323",
        "LegacyStatus": "MATCH",
        "OwningBusiness": "DCC AU"
        }]
        */
        try {

            var excelRowArray = [];

            //getting the attachment
            var getAttachment = new GlideRecord('sys_attachment');
            getAttachment.addEncodedQuery('table_sys_id=' + bulkRecID);
            getAttachment.query();
            if (getAttachment.next()) {
                var attachmentRec = getAttachment.getValue('sys_id');
            }
            //getting attachment

            var attachment = new GlideSysAttachment(); //method to get the contents of the attachment
            var attachmentDetails = attachment.getContentStream(attachmentRec); //getting content of the EXcel

            var parser = new sn_impex.GlideExcelParser(); //method to parse the content of the Excel
            parser.setSource(attachmentDetails); //setting the source to parse the content from the stream

            var getSheet = parser.getSheetNames(); //getting the sheet name to fetch details
            parser.setSheetName(getSheet); //setting the sheet to parse

            if (parser.parse()) { //converting into readable format using parse

                while (parser.next()) { //iterating over each row
                    var getRows = parser.getRow(); //reading row by row
                    var rowObj = JSON.stringify(getRows); //holds the rows of Excel as comma sepearated
                    excelRowArray.push(rowObj + '');

                }
            }

            return excelRowArray;

        } catch (ex) {
            gs.info('Error Received from tradeLevelParse ' + ex);
        }


    },


    errorRecordReasons: function(invalidKey) {

        var errorReason = '';

        switch (invalidKey) {

            case 'invalidTransRef':
                errorReason = 'Trade Reference provided does not exist for ';
                break;


            case 'unavailableTrade':
                errorReason = 'Trade Reference provided does not exist in iQube Database.';
                break;

            case 'default':
                errorReason = '';
                break;

        }

        return errorReason;



    },


    bulkErrorValidation: function(bulkexcelRowArray, bulkRecID, owningBusiness) {

        /*
        	This function will segregate the valid and invalid records received from bulkLevelParse or tradeLevelParse functions and
        	pass to createBulkCaseTask and populateErrorRecord for for valid records & invalid records respectively

        	Sample Output for Error Records

        	[{
        	"tradeRef": "D-2025167-00-0",
        	"tradeMarket": "DCC HK",
        	"inValidReason": "Trade Reference provided does not exist in iQube Database"
        	}, {
        	"tradeRef": "D-076352-00-0",
            "tradeMarket": "DCC HK",
            "inValidReason": "Trade Reference provided does not exist for DCC HK"
        	}]
        	---------------------------------------------------------------------
        	Sample output for valid Records
        	[{
        	"tradeID": "8e9d44ec3b0d62d0fca5a7da26e45a86",
        	"tradeMarket": "DCC HK"
        	}, {
        		"tradeID": "46ad8c243bcd2a10092ed79704e45ade",
        	"tradeMarket": "DCC HK"
        	}]
        */

        try {
            var errorObj = {};
            var errorRecords = [];
            var validRecords = [];
            var filterArray = new global.ArrayUtil();
            gs.info('Length of array ' + bulkexcelRowArray.length);

            for (var i = 0; i < bulkexcelRowArray.length; i++) {

                (function executeRow(index) {

                    var getData = JSON.parse(bulkexcelRowArray[i]);
                    var trdRef = getData.tradeReference; //Change name as per Excel Sheet
                    var trdMarket = owningBusiness.toString(); //Change name as per Excel Sheet

                    if (trdRef != null || trdRef != undefined) { //error handling

                        //gs.info('trdRef ' + trdRef);
                        // gs.info('trdMarket ' + trdMarket);

                        var getTradeData = new GlideRecord('x_938076_now_utils_custody_trades');
                        getTradeData.addEncodedQuery('transaction_reference=' + trdRef + '^owning_business.owning_business=' + trdMarket);
                        getTradeData.query();
                        if (getTradeData.next()) {

                            var countOfTrades = parseInt(getTradeData.getRowCount());

                            // gs.info('trdMarket Count  ' + countOfTrades);



                            if (countOfTrades == 1) {
                                validRecords.push(getTradeData.sys_id + ' ');

                            } else { //Duplicate Trades

                                //Error Records
                                errorObj.tradeRef = trdRef.toString();
                                errorObj.tradeMarket = trdMarket.toString();
                                errorObj.inValidReason = 'Duplicate Trade Reference found for ' + trdRef.toString() + '.';
                                errorRecords.push(JSON.stringify(errorObj) + ' ');
                                //Error Records
                            }

                        } else {
                            //Reason Logic

                            var reasonCode = '';
                            var validateTrade = new GlideRecord('x_938076_now_utils_custody_trades');
                            validateTrade.addEncodedQuery('transaction_reference=' + trdRef);
                            validateTrade.query();
                            if (validateTrade.next()) {
                                //Valid trade reference but belongs to different market than selected
                                if (validateTrade.owning_business.owning_business.toString() != trdMarket.toString()) {
                                    reasonCode = 'Trade Reference provided does not exist for ' + trdMarket.toString() + '.';

                                }
                            } else { //InValid trade reference not avialable with reference to iQube
                                reasonCode = 'Trade Reference provided does not exist in iQube Database.';
                            }
                            //Error Records
                            errorObj.tradeRef = trdRef.toString();
                            errorObj.tradeMarket = trdMarket.toString();
                            errorObj.inValidReason = reasonCode.toString();
                            errorRecords.push(JSON.stringify(errorObj) + ' ');
                            //Error Records
                        }

                    }
                })(i);

            }

            errorRecords = filterArray.unique(errorRecords);
            validRecords = filterArray.unique(validRecords);

            //update bulk with error record

            //this.createBulkCaseTask(validRecords, bulkRecID);
            //this.populateErrorRecord(errorRecords, bulkRecID);
            //this.populateErrorRecord(errorRecords);


            //gs.info('errorRecords ' + '[' + errorRecords.toString() + ']');
            //gs.info('validRecords ' + validRecords.toString());


            return errorRecords;

        } catch (ex) {
            gs.info('Error Received from bulkErrorValidation ' + ex);
        }

    },


    createBulkCaseTask: function(validRecords, bulkRecID) {
        for (var i = 0; i < validRecords.length; i++) {

            (function createBulkCase(index) {
                var grcustodycase = new GlideRecord("x_hsb11_mss_c_proc_mss_custody_case");
                grcustodycase.initialize();
                grcustodycase.short_description = 'Manually triggered by Bulk processing';
                grcustodycase.description = 'Manually triggered by Bulk processing';
                grcustodycase.trade_id = validRecords[i];
                grcustodycase.bulk_id = bulkRecID;
                grcustodycase.state = 2;
                grcustodycase.triggered_by = '19c79fbb1ba30a10c6ada6c7b04bcbd5';
                grcustodycase.case_status = 'ec34a3731b270a10c6ada6c7b04bcb7a';
                var caseSysId = grcustodycase.insert();
                gs.info('Created custody case: ' + caseSysId);
            })(i);

        }

    },

    checkValidationStatus: function() {

        /* The array of invalid trades received from bulkErrorValidation 
        will be utilized to populate the new field(TBD) in submitted bulk which will be utilized for the display of audit log*/

        try {
            var owningBusiness = this.getParameter('sysparm_market');
            var bulkexcelRowArray = [];
            var errorObj = {};
            var errorRecords = [];
            var validRecords = [];
            var filterArray = new global.ArrayUtil();
            //getting the attachment
            var currentUser = gs.getUser().getName(); //to fetch the right attachment by user
            var getTempAttachment = new GlideRecord("sys_attachment");
            getTempAttachment.addEncodedQuery("table_name=ZZ_YYsc_cart_item^sys_created_by=" + currentUser);
            getTempAttachment.orderByDesc('sys_created_on');
            getTempAttachment.query();
            if (getTempAttachment.next()) {
                var attachmentSysId = getTempAttachment.getValue('sys_id');
            }
            //getting attachment

            var bulkattachment = new GlideSysAttachment(); //method to get the contents of the attachment
            var bulkattachmentDetails = bulkattachment.getContentStream(attachmentSysId); //getting content of the EXcel

            var bulkparser = new sn_impex.GlideExcelParser(); //method to parse the content of the Excel
            bulkparser.setSource(bulkattachmentDetails); //setting the source to parse the content from the stream

            var bulkgetSheet = bulkparser.getSheetNames(); //getting the sheet name to fetch details
            bulkparser.setSheetName(bulkgetSheet); //setting the sheet to parse

            if (bulkparser.parse()) { //converting into readable format using parse

                while (bulkparser.next()) { //iterating over each row
                    var bulkgetRows = bulkparser.getRow(); //reading row by row
                    bulkgetRows.business = owningBusiness.toString(); //add the owning business for each array item which will be used for error validation which will be from record producer
                    var bulkrowObj = JSON.stringify(bulkgetRows); //holds the rows of Excel as comma sepearated
                    bulkexcelRowArray.push(bulkrowObj + '');

                }
            }

            gs.info('Client Validation Bulk upload ' + bulkexcelRowArray.toString());

            var recordsinExcel = parseInt(bulkexcelRowArray.length);

            gs.info('Client Validation Bulk upload Length ' + recordsinExcel);


            //return bulkexcelRowArray;

            if (recordsinExcel > 0) {


                for (var i = 0; i < bulkexcelRowArray.length; i++) {

                    (function executeRow(index) {

                        var getData = JSON.parse(bulkexcelRowArray[i]);
                        var trdRef = getData.tradeReference; //Change name as per Excel Sheet
                        var trdMarket = owningBusiness.toString(); //Change name as per Excel Sheet

                        if (trdRef != null || trdRef != undefined) { //error handling

                            gs.info('trdRef ' + trdRef);
                            gs.info('trdMarket ' + trdMarket);

                            var getTradeData = new GlideRecord('x_938076_now_utils_custody_trades');
                            getTradeData.addEncodedQuery('transaction_reference=' + trdRef + '^owning_business.owning_business=' + trdMarket);
                            getTradeData.query();
                            if (getTradeData.next()) {

                                gs.info('trdMarket ' + 'Loop 1');

                                var countOfTrades = parseInt(getTradeData.getRowCount());

                                // gs.info('trdMarket Count  ' + countOfTrades);



                                if (countOfTrades == 1) {
                                    validRecords.push(getTradeData.sys_id + ' ');

                                } else { //Duplicate Trades

                                    //Error Records
                                    errorObj.tradeRef = trdRef.toString();
                                    errorObj.tradeMarket = trdMarket.toString();
                                    errorObj.inValidReason = 'Duplicate Trade Reference found for ' + trdRef.toString() + '.';
                                    errorRecords.push(JSON.stringify(errorObj) + ' ');
                                    //Error Records
                                }

                            } else {
                                //Reason Logic

                                gs.info('trdMarket ' + 'Loop 2');

                                var reasonCode = '';
                                var validateTrade = new GlideRecord('x_938076_now_utils_custody_trades');
                                validateTrade.addEncodedQuery('transaction_reference=' + trdRef);
                                validateTrade.query();
                                if (validateTrade.next()) {
                                    //Valid trade reference but belongs to different market than selected
                                    if (validateTrade.owning_business.owning_business.toString() != trdMarket.toString()) {
                                        reasonCode = 'Trade Reference provided does not exist for ' + trdMarket.toString() + '.';

                                    }
                                } else { //InValid trade reference not avialable with reference to iQube
                                    reasonCode = 'Trade Reference provided does not exist in iQube Database.';
                                }
                                //Error Records
                                errorObj.tradeRef = trdRef.toString();
                                errorObj.tradeMarket = trdMarket.toString();
                                errorObj.inValidReason = reasonCode.toString();
                                errorRecords.push(JSON.stringify(errorObj) + ' ');
                                //Error Records
                            }

                        }
                    })(i);

                }

                errorRecords = filterArray.unique(errorRecords);

                gs.info('Client Validation Bulk upload ' + errorRecords.length);
                gs.info('Client Validation Bulk upload ' + errorRecords.toString());



                if (errorRecords.length > 0) {

                    if (errorRecords.length <= 10) { // allowing partial errors
                        return 'Allow Partially';

                    } else {
                        return 'Errors Found';
                    }


                } else {
                    return 'No Errors';
                }

            }
            return 'No records Found'; //empty file

        } catch (ex) {
            gs.info('Error Received from bulkLevelParse ' + ex);
        }
    },





    type: 'MSSCustodyBulkFileUpload'
});
